
const WORDS=[{"id": 0, "w": "成语", "p": "chéngyǔ", "t": "名词", "m": "thành ngữ", "coll": "学习成语、成语故事", "s": "老师用一个故事解释了这个成语的意思。"}, {"id": 1, "w": "则", "p": "zé", "t": "量词", "m": "mẩu, bản (dùng cho bài văn/mục)", "coll": "一则消息、两则故事", "s": "今天的报纸上有一则关于环保的消息。"}, {"id": 2, "w": "盲人", "p": "mángrén", "t": "名词", "m": "người mù", "coll": "帮助盲人、盲人朋友", "s": "她经常帮助那位盲人过马路。"}, {"id": 3, "w": "摸", "p": "mō", "t": "动词", "m": "mò, sờ", "coll": "摸一摸、摸着头", "s": "妈妈轻轻地摸了摸孩子的头。"}, {"id": 4, "w": "大象", "p": "dàxiàng", "t": "名词", "m": "con voi", "coll": "一头大象、大象的鼻子", "s": "那头大象用长长的鼻子卷起了地上的树枝。"}, {"id": 5, "w": "智慧", "p": "zhìhuì", "t": "名词", "m": "trí tuệ, sự sáng suốt", "coll": "充满智慧、生活的智慧", "s": "这位老人的话里充满了生活的智慧。"}, {"id": 6, "w": "士兵", "p": "shìbīng", "t": "名词", "m": "binh lính", "coll": "一名士兵、年轻的士兵", "s": "那名士兵帮助村民把受伤的人送到了医院。"}, {"id": 7, "w": "瞎", "p": "xiā", "t": "动词／副词", "m": "bị mù; vớ vẩn", "coll": "瞎说、瞎猜", "s": "没有弄清楚事情的经过，就不要瞎说。"}, {"id": 8, "w": "分别", "p": "fēnbié", "t": "副词", "m": "riêng rẽ, từng người", "coll": "分别介绍、分别回答", "s": "请这三位同学分别介绍一下自己的家乡。"}, {"id": 9, "w": "寻找", "p": "xúnzhǎo", "t": "动词", "m": "tìm", "coll": "寻找机会、寻找钥匙", "s": "他正在房间里寻找丢失的钥匙。"}, {"id": 10, "w": "牙齿", "p": "yáchǐ", "t": "名词", "m": "răng", "coll": "保护牙齿、牙齿整齐", "s": "每天认真刷牙，有助于保护牙齿。"}, {"id": 11, "w": "胡说", "p": "húshuō", "t": "动词", "m": "nói bậy, nói bừa", "coll": "别胡说、胡说八道", "s": "这件事明明不是他做的，你别胡说。"}, {"id": 12, "w": "尾巴", "p": "wěiba", "t": "名词", "m": "cái đuôi", "coll": "一条尾巴、摇尾巴", "s": "小狗摇着尾巴，高兴地跑到了主人身边。"}, {"id": 13, "w": "绳子", "p": "shéngzi", "t": "名词", "m": "dây thừng", "coll": "一根绳子、用绳子绑", "s": "他用一根绳子把箱子绑在了自行车后面。"}, {"id": 14, "w": "平", "p": "píng", "t": "形容词", "m": "bằng phẳng", "coll": "地面很平、平的路面", "s": "这块地很平，适合搭帐篷。"}, {"id": 15, "w": "墙", "p": "qiáng", "t": "名词", "m": "(bức) tường", "coll": "一面墙、墙上的画", "s": "这面墙上挂着一幅美丽的画。"}, {"id": 16, "w": "扇子", "p": "shànzi", "t": "名词", "m": "(cái) quạt", "coll": "一把扇子、拿着扇子", "s": "天气很热，奶奶拿着扇子坐在树下。"}, {"id": 17, "w": "片面", "p": "piànmiàn", "t": "形容词", "m": "phiến diện", "coll": "片面的看法、避免片面", "s": "只听一个人的意见，就下结论，这样的看法太片面了。"}, {"id": 18, "w": "结论", "p": "jiélùn", "t": "名词", "m": "kết luận", "coll": "得出结论、下结论", "s": "看完所有材料后，我们得出了相同的结论。"}, {"id": 19, "w": "精诚所至，金石为开", "p": "jīngchéng suǒzhì, jīnshí wéikāi", "t": "成语", "m": "lòng thành có thể làm mọi việc nan giải được giải quyết.", "coll": "精诚所至，金石为开、用诚心感动别人", "s": "老师用“精诚所至，金石为开”这句成语鼓励我们坚持努力。"}, {"id": 20, "w": "将军", "p": "jiāngjūn", "t": "名词", "m": "tướng quân", "coll": "一位将军、将军的命令", "s": "故事中的将军带领士兵们安全地回到了城里。"}, {"id": 21, "w": "善于", "p": "shànyú", "t": "动词", "m": "giỏi về, có sở trường", "coll": "善于思考、善于沟通", "s": "她善于发现问题，也善于解决问题。"}, {"id": 22, "w": "称", "p": "chēng", "t": "动词", "m": "gọi là, tán dương", "coll": "称为、被称为", "s": "人们把这位热心的老人称为“社区好邻居”。"}, {"id": 23, "w": "打猎", "p": "dǎ liè", "t": "动词", "m": "đi săn", "coll": "外出打猎、打猎的故事", "s": "这篇课文讲的是一位将军外出打猎的故事。"}, {"id": 24, "w": "忽然", "p": "hūrán", "t": "副词", "m": "thình lình, bỗng nhiên", "coll": "忽然想起、忽然下雨", "s": "走到门口时，他忽然想起忘带钥匙了。"}, {"id": 25, "w": "蹲", "p": "dūn", "t": "动词", "m": "ngồi xổm", "coll": "蹲下来、蹲在地上", "s": "她蹲下来，耐心地和孩子说话。"}, {"id": 26, "w": "摇", "p": "yáo", "t": "动词", "m": "lắc, vẫy", "coll": "摇摇头、摇着尾巴", "s": "听到这个问题，他轻轻地摇了摇头。"}, {"id": 27, "w": "不要紧", "p": "bú yàojǐn", "t": "形容词", "m": "không hề gì, không sao cả", "coll": "不要紧、摔一下不要紧", "s": "这次没考好不要紧，下次继续努力。"}, {"id": 28, "w": "支", "p": "zhī", "t": "量词", "m": "cây (dùng cho vật dài, mảnh)", "coll": "一支笔、一支箭", "s": "请借给我一支铅笔。"}, {"id": 29, "w": "摆", "p": "bǎi", "t": "动词", "m": "bày biện, sắp đặt (tư thế)", "coll": "摆整齐、摆好姿势", "s": "她把桌子上的书摆整齐了。"}, {"id": 30, "w": "姿势", "p": "zīshì", "t": "名词", "m": "tư thế", "coll": "正确的姿势、坐的姿势", "s": "读书时，我们应该保持正确的姿势。"}, {"id": 31, "w": "全神贯注", "p": "quánshén guànzhù", "t": "成语", "m": "tập trung tinh thần", "coll": "全神贯注地听、全神贯注地工作", "s": "同学们全神贯注地听着老师的讲解。"}, {"id": 32, "w": "尽力", "p": "jìnlì", "t": "动词", "m": "gắng hết sức", "coll": "尽力帮助、尽力完成", "s": "虽然任务很难，他还是尽力完成了。"}, {"id": 33, "w": "反应", "p": "fǎnyìng", "t": "动词／名词", "m": "phản ứng; sự phản ứng", "coll": "反应很快、作出反应", "s": "听到这个意外的消息，他一时没有反应过来。"}, {"id": 34, "w": "确定", "p": "quèdìng", "t": "动词", "m": "xác định, khẳng định", "coll": "确定时间、确定方向", "s": "出发前，我们需要确定集合的时间。"}, {"id": 35, "w": "石头", "p": "shítou", "t": "名词", "m": "đá", "coll": "一块石头、捡石头", "s": "孩子在河边捡到了一块圆圆的石头。"}, {"id": 36, "w": "连续", "p": "liánxù", "t": "动词", "m": "liên tục, liên tiếp", "coll": "连续三天、连续工作", "s": "他已经连续工作了五个小时。"}, {"id": 37, "w": "根", "p": "gēn", "t": "名词／量词", "m": "rễ cây; chiếc, cái", "coll": "一根绳子、树根", "s": "爸爸找来一根绳子，把门绑好了。"}, {"id": 38, "w": "碎", "p": "suì", "t": "动词／形容词", "m": "vỡ; vụn vặt", "coll": "打碎了、碎成几块", "s": "杯子掉到地上，一下子就碎了。"}, {"id": 39, "w": "杆", "p": "gǎn", "t": "名词", "m": "cán, báng", "coll": "一根旗杆、笔杆", "s": "操场中央立着一根高高的旗杆。"}, {"id": 40, "w": "哎", "p": "āi", "t": "叹词", "m": "chà, trời ơi", "coll": "哎，你好、哎，等一下", "s": "哎，你的书还放在桌子上呢！"}, {"id": 41, "w": "唉", "p": "ài", "t": "叹词", "m": "than ôi, chao ôi", "coll": "唉，真可惜、唉，没办法", "s": "唉，这场比赛只差一分就赢了。"}, {"id": 42, "w": "金属", "p": "jīnshǔ", "t": "名词", "m": "kim loại", "coll": "金属材料、一块金属", "s": "这个盒子是用金属做成的。"}, {"id": 43, "w": "硬", "p": "yìng", "t": "形容词", "m": "cứng, rắn", "coll": "石头很硬、硬的面包", "s": "这块面包放了几天，已经变得很硬了。"}, {"id": 44, "w": "便", "p": "biàn", "t": "副词", "m": "thì, bèn, là", "coll": "说完便走、一……便……", "s": "听到下课铃声，他便收起了课本。"}];
const CHUNKS=[["老师", "用一个故事", "解释了", "这个成语的意思。"], ["今天的报纸上", "有", "一则", "关于环保的消息。"], ["她", "经常", "帮助那位盲人", "过马路。"], ["妈妈", "轻轻地", "摸了摸", "孩子的头。"], ["那头大象", "用长长的鼻子", "卷起了", "地上的树枝。"], ["这位老人", "的话里", "充满了", "生活的智慧。"], ["那名士兵", "帮助村民", "把受伤的人", "送到了医院。"], ["没有", "弄清楚事情的经过，", "就", "不要瞎说。"], ["请", "这三位同学", "分别", "介绍一下自己的家乡。"], ["他", "正在", "房间里", "寻找丢失的钥匙。"], ["每天", "认真刷牙，", "有助于", "保护牙齿。"], ["这件事", "明明不是他做的，", "你", "别胡说。"], ["小狗", "摇着尾巴，", "高兴地", "跑到了主人身边。"], ["他", "用一根绳子", "把箱子", "绑在了自行车后面。"], ["这块地", "很平，", "适合", "搭帐篷。"], ["这面墙上", "挂着", "一幅", "美丽的画。"], ["天气很热，", "奶奶", "拿着扇子", "坐在树下。"], ["只听一个人的意见，", "就下结论，", "这样的看法", "太片面了。"], ["看完所有材料后，", "我们", "得出了", "相同的结论。"], ["老师", "用“精诚所至，金石为开”", "这句成语", "鼓励我们坚持努力。"], ["故事中的将军", "带领士兵们", "安全地", "回到了城里。"], ["她", "善于", "发现问题，", "也善于解决问题。"], ["人们", "把这位热心的老人", "称为", "“社区好邻居”。"], ["这篇课文", "讲的是", "一位将军", "外出打猎的故事。"], ["走到门口时，", "他", "忽然想起", "忘带钥匙了。"], ["她", "蹲下来，", "耐心地", "和孩子说话。"], ["听到这个问题，", "他", "轻轻地", "摇了摇头。"], ["这次", "没考好", "不要紧，", "下次继续努力。"], ["请", "借给我", "一支", "铅笔。"], ["她", "把", "桌子上的书", "摆整齐了。"], ["读书时，", "我们", "应该", "保持正确的姿势。"], ["同学们", "全神贯注地", "听着", "老师的讲解。"], ["虽然任务很难，", "他", "还是", "尽力完成了。"], ["听到", "这个意外的消息，", "他", "一时没有反应过来。"], ["出发前，", "我们", "需要", "确定集合的时间。"], ["孩子", "在河边", "捡到了", "一块圆圆的石头。"], ["他", "已经", "连续工作了", "五个小时。"], ["爸爸", "找来", "一根绳子，", "把门绑好了。"], ["杯子", "掉到地上，", "一下子", "就碎了。"], ["操场中央", "立着", "一根", "高高的旗杆。"], ["哎，", "你的书", "还", "放在桌子上呢！"], ["唉，", "这场比赛", "只差一分", "就赢了。"], ["这个盒子", "是", "用金属", "做成的。"], ["这块面包", "放了几天，", "已经", "变得很硬了。"], ["听到", "下课铃声，", "他", "便收起了课本。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai7-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/45 个词语。学完五组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),45)}<div class="ntc-progressgroups">${[0,1,2,3,4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共45个词语，点击 ↗ 学习该词语',totalLearned()+'/45 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、5个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===44;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<44){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:4};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课45个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课45个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [12, 13, 16], "1": [12, 13, 16], "2": [27, 32, 44], "3": [12, 13, 16], "4": [12, 13, 16], "5": [27, 32, 44], "6": [12, 13, 16], "7": [12, 13, 16], "8": [12, 13, 16], "9": [12, 13, 16], "10": [12, 13, 16], "11": [12, 13, 16], "12": [12, 13, 16], "13": [12, 13, 16], "14": [27, 32, 44], "15": [12, 13, 16], "16": [12, 13, 16], "17": [27, 32, 44], "18": [12, 13, 16], "19": [12, 13, 16], "20": [27, 32, 44], "21": [12, 13, 16], "22": [12, 13, 16], "23": [12, 13, 16], "24": [12, 13, 16], "25": [12, 13, 16], "26": [27, 32, 44], "27": [12, 13, 16], "28": [12, 13, 16], "29": [27, 32, 44], "30": [12, 13, 16], "31": [12, 13, 16], "32": [12, 13, 16], "33": [12, 13, 16], "34": [12, 13, 16], "35": [27, 32, 44], "36": [12, 13, 16], "37": [12, 13, 16], "38": [27, 32, 44], "39": [12, 13, 16], "40": [12, 13, 16], "41": [12, 13, 16], "42": [12, 13, 16], "43": [12, 13, 16], "44": [12, 13, 16]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的45个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第7课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第7课学习进度','第7课 · 45个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 45</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2,3,4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第7课';$('ntc-bookmark').textContent=student?total+'/45 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2,3,4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2,3,4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第7课学习进度</div><div style="padding:0 10px">'+total+'/45 个已学词语'+meter(total,45)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"成语":"data:audio/mpeg;base64,","老师用一个故事解释了这个成语的意思。":"data:audio/mpeg;base64,","则":"data:audio/mpeg;base64,","今天的报纸上有一则关于环保的消息。":"data:audio/mpeg;base64,","盲人":"data:audio/mpeg;base64,","她经常帮助那位盲人过马路。":"data:audio/mpeg;base64,","摸":"data:audio/mpeg;base64,","妈妈轻轻地摸了摸孩子的头。":"data:audio/mpeg;base64,","大象":"data:audio/mpeg;base64,","那头大象用长长的鼻子卷起了地上的树枝。":"data:audio/mpeg;base64,","智慧":"data:audio/mpeg;base64,","这位老人的话里充满了生活的智慧。":"data:audio/mpeg;base64,","士兵":"data:audio/mpeg;base64,","那名士兵帮助村民把受伤的人送到了医院。":"data:audio/mpeg;base64,","瞎":"data:audio/mpeg;base64,","没有弄清楚事情的经过，就不要瞎说。":"data:audio/mpeg;base64,","分别":"data:audio/mpeg;base64,","请这三位同学分别介绍一下自己的家乡。":"data:audio/mpeg;base64,","寻找":"data:audio/mpeg;base64,","他正在房间里寻找丢失的钥匙。":"data:audio/mpeg;base64,","牙齿":"data:audio/mpeg;base64,","每天认真刷牙，有助于保护牙齿。":"data:audio/mpeg;base64,","胡说":"data:audio/mpeg;base64,","这件事明明不是他做的，你别胡说。":"data:audio/mpeg;base64,","尾巴":"data:audio/mpeg;base64,","小狗摇着尾巴，高兴地跑到了主人身边。":"data:audio/mpeg;base64,","绳子":"data:audio/mpeg;base64,","他用一根绳子把箱子绑在了自行车后面。":"data:audio/mpeg;base64,","平":"data:audio/mpeg;base64,","这块地很平，适合搭帐篷。":"data:audio/mpeg;base64,","墙":"data:audio/mpeg;base64,","这面墙上挂着一幅美丽的画。":"data:audio/mpeg;base64,","扇子":"data:audio/mpeg;base64,","天气很热，奶奶拿着扇子坐在树下。":"data:audio/mpeg;base64,","片面":"data:audio/mpeg;base64,","只听一个人的意见，就下结论，这样的看法太片面了。":"data:audio/mpeg;base64,","结论":"data:audio/mpeg;base64,","看完所有材料后，我们得出了相同的结论。":"data:audio/mpeg;base64,","精诚所至，金石为开":"data:audio/mpeg;base64,","老师用“精诚所至，金石为开”这句成语鼓励我们坚持努力。":"data:audio/mpeg;base64,","将军":"data:audio/mpeg;base64,","故事中的将军带领士兵们安全地回到了城里。":"data:audio/mpeg;base64,","善于":"data:audio/mpeg;base64,","她善于发现问题，也善于解决问题。":"data:audio/mpeg;base64,","称":"data:audio/mpeg;base64,","人们把这位热心的老人称为“社区好邻居”。":"data:audio/mpeg;base64,","打猎":"data:audio/mpeg;base64,","这篇课文讲的是一位将军外出打猎的故事。":"data:audio/mpeg;base64,","忽然":"data:audio/mpeg;base64,","走到门口时，他忽然想起忘带钥匙了。":"data:audio/mpeg;base64,","蹲":"data:audio/mpeg;base64,","她蹲下来，耐心地和孩子说话。":"data:audio/mpeg;base64,","摇":"data:audio/mpeg;base64,","听到这个问题，他轻轻地摇了摇头。":"data:audio/mpeg;base64,","不要紧":"data:audio/mpeg;base64,","这次没考好不要紧，下次继续努力。":"data:audio/mpeg;base64,","支":"data:audio/mpeg;base64,","请借给我一支铅笔。":"data:audio/mpeg;base64,","摆":"data:audio/mpeg;base64,","她把桌子上的书摆整齐了。":"data:audio/mpeg;base64,","姿势":"data:audio/mpeg;base64,","读书时，我们应该保持正确的姿势。":"data:audio/mpeg;base64,","全神贯注":"data:audio/mpeg;base64,","同学们全神贯注地听着老师的讲解。":"data:audio/mpeg;base64,","尽力":"data:audio/mpeg;base64,","虽然任务很难，他还是尽力完成了。":"data:audio/mpeg;base64,","反应":"data:audio/mpeg;base64,","听到这个意外的消息，他一时没有反应过来。":"data:audio/mpeg;base64,","确定":"data:audio/mpeg;base64,","出发前，我们需要确定集合的时间。":"data:audio/mpeg;base64,","石头":"data:audio/mpeg;base64,","孩子在河边捡到了一块圆圆的石头。":"data:audio/mpeg;base64,","连续":"data:audio/mpeg;base64,","他已经连续工作了五个小时。":"data:audio/mpeg;base64,","根":"data:audio/mpeg;base64,","爸爸找来一根绳子，把门绑好了。":"data:audio/mpeg;base64,","碎":"data:audio/mpeg;base64,","杯子掉到地上，一下子就碎了。":"data:audio/mpeg;base64,","杆":"data:audio/mpeg;base64,","操场中央立着一根高高的旗杆。":"data:audio/mpeg;base64,","哎":"data:audio/mpeg;base64,","哎，你的书还放在桌子上呢！":"data:audio/mpeg;base64,","唉":"data:audio/mpeg;base64,","唉，这场比赛只差一分就赢了。":"data:audio/mpeg;base64,","金属":"data:audio/mpeg;base64,","这个盒子是用金属做成的。":"data:audio/mpeg;base64,","硬":"data:audio/mpeg;base64,","这块面包放了几天，已经变得很硬了。":"data:audio/mpeg;base64,","便":"data:audio/mpeg;base64,","听到下课铃声，他便收起了课本。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai7-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai7_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai7-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=45)||!p.memory)throw Error();if(!confirm('恢复第7课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<45;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<45&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第7课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

